import { test, expect } from '@playwright/test';

test.describe('Bottom Sheet Dropdown Replacement on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should replace dropdowns with bottom sheet on mobile view', async ({ page }) => {
    // Setup: intercept dropdown API calls
    await page.route('**/api/dropdowns/options', (route) => {
      route.abort('API call intercepted');
    });

    // Verify dropdown is visible on desktop
    const dropdownMenu = page.getByRole('button', { name: /filter options/i });
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown contains options
    const dropdownOptions = page.getByRole('option', { name: /option 1/i });
    await expect(dropdownOptions).toBeVisible();

    // Verify dropdown has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify dropdown is not visible on mobile
    await page.setViewportSize({ width: 375, height: 812 });
    await expect(dropdownMenu).not.toBeVisible();

    // Verify bottom sheet appears
    const bottomSheet = page.getByRole('dialog', { name: /filter options/i });
    await expect(bottomSheet).toBeVisible();

    // Verify bottom sheet has close button
    const bottomSheetCloseButton = page.getByRole('button', { name: /close/i });
    await expect(bottomSheetCloseButton).toBeVisible();

    // Verify bottom sheet contains options
    const bottomSheetOptions = page.getByRole('option', { name: /option 1/i });
    await expect(bottomSheetOptions).toBeVisible();

    // Verify bottom sheet is responsive
    await expect(bottomSheet).toHaveAttribute('aria-label', /filter options/i);
    await expect(bottomSheet).toHaveAttribute('aria-describedby', /filter options/i);

    // Verify bottom sheet is accessible
    await expect(bottomSheetCloseButton).toBeAccessible();

    // Verify dropdown is hidden when bottom sheet is open
    await expect(dropdownMenu).not.toBeVisible();

    // Verify bottom sheet is closed when clicking close button
    await bottomSheetCloseButton.click();
    await expect(bottomSheet).not.toBeVisible();

    // Verify dropdown is visible again on desktop
    await page.setViewportSize({ width: 1024, height: 768 });
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown is not visible on mobile
    await page.setViewportSize({ width: 375, height: 812 });
    await expect(dropdownMenu).not.toBeVisible();
  });

  test('should handle bottom sheet close and reopen on mobile', async ({ page }) => {
    // Setup: intercept dropdown API calls
    await page.route('**/api/dropdowns/options', (route) => {
      route.abort('API call intercepted');
    });

    // Verify dropdown is visible on desktop
    const dropdownMenu = page.getByRole('button', { name: /filter options/i });
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown contains options
    const dropdownOptions = page.getByRole('option', { name: /option 1/i });
    await expect(dropdownOptions).toBeVisible();

    // Verify dropdown has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify bottom sheet appears on mobile
    await page.setViewportSize({ width: 375, height: 812 });
    const bottomSheet = page.getByRole('dialog', { name: /filter options/i });
    await expect(bottomSheet).toBeVisible();

    // Verify bottom sheet has close button
    const bottomSheetCloseButton = page.getByRole('button', { name: /close/i });
    await expect(bottomSheetCloseButton).toBeVisible();

    // Verify bottom sheet contains options
    const bottomSheetOptions = page.getByRole('option', { name: /option 1/i });
    await expect(bottomSheetOptions).toBeVisible();

    // Verify bottom sheet is responsive
    await expect(bottomSheet).toHaveAttribute('aria-label', /filter options/i);
    await expect(bottomSheet).toHaveAttribute('aria-describedby', /filter options/i);

    // Verify bottom sheet is accessible
    await expect(bottomSheetCloseButton).toBeAccessible();

    // Verify dropdown is hidden when bottom sheet is open
    await expect(dropdownMenu).not.toBeVisible();

    // Verify bottom sheet is closed when clicking close button
    await bottomSheetCloseButton.click();
    await expect(bottomSheet).not.toBeVisible();

    // Verify dropdown is visible again on desktop
    await page.setViewportSize({ width: 1024, height: 768 });
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown is not visible on mobile
    await page.setViewportSize({ width: 375, height: 812 });
    await expect(dropdownMenu).not.toBeVisible();

    // Verify bottom sheet reappears when clicking close button again
    await bottomSheetCloseButton.click();
    await expect(bottomSheet).toBeVisible();

    // Verify dropdown is hidden when bottom sheet is open
    await expect(dropdownMenu).not.toBeVisible();

    // Verify bottom sheet is closed when clicking close button again
    await bottomSheetCloseButton.click();
    await expect(bottomSheet).not.toBeVisible();

    // Verify dropdown is visible again on desktop
    await page.setViewportSize({ width: 1024, height: 768 });
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown is not visible on mobile
    await page.setViewportSize({ width: 375, height: 812 });
    await expect(dropdownMenu).not.toBeVisible();
  });
});
